    $router->get('/api/whatsapp/webhook', static function (Request $request) use ($whatsappWebhook): Response {
        $mode=$request->queryValue('hub.mode',$request->queryValue('hub_mode'));
        $token=$request->queryValue('hub.verify_token',$request->queryValue('hub_verify_token'));
        $challenge=$request->queryValue('hub.challenge',$request->queryValue('hub_challenge'));
        $answer=$whatsappWebhook->challenge(is_string($mode)?$mode:null,is_string($token)?$token:null,is_string($challenge)?$challenge:null);
        return $answer===null?Response::text("Verificação recusada.\n",403):Response::text($answer);
    });
    $router->postWithoutCsrf('/api/whatsapp/webhook', static function (Request $request) use ($whatsappWebhook,$whatsappMessages,$whatsappCloudApi,$whatsappMedia): Response {
        if(!$whatsappWebhook->validSignature($request->body(),$request->header('x-hub-signature-256')))return Response::text("Assinatura inválida.\n",401);
        $payload=json_decode($request->body(),true);
        if(!is_array($payload))return Response::text("JSON inválido.\n",400);
        $whatsappMessages->receive($payload,$whatsappCloudApi,$whatsappMedia);
        return Response::text("EVENT_RECEIVED\n");
    });
    $router->postWithoutCsrf('/api/asaas/webhook',static function(Request$request)use($asaasWebhook,$finance,$financeCatalog,$studentEnrollments,$avaEnrollmentReleaser,$avaAccessNotifier):Response{
        if(!$asaasWebhook->valid($request->header('asaas-access-token')))return Response::text("Acesso recusado.\n",401);
        $payload=json_decode($request->body(),true);if(!is_array($payload))return Response::text("JSON inválido.\n",400);
        $eventId=trim((string)($payload['id']??''));$eventType=trim((string)($payload['event']??''));$payment=is_array($payload['payment']??null)?$payload['payment']:null;$subscription=is_array($payload['subscription']??null)?$payload['subscription']:null;$checkout=is_array($payload['checkout']??null)?$payload['checkout']:null;
        if($eventId===''||$eventType==='')return Response::text("Evento inválido.\n",400);
        $resource=$payment??$subscription??$checkout;if(!$finance->registerWebhook($eventId,$eventType,is_array($resource)?(string)($resource['id']??''):null))return Response::text("EVENT_RECEIVED\n");
        try{if($payment!==null){$reference=(string)($payment['externalReference']??'');if(str_starts_with($reference,'mundo-inter:sandbox:franchise-test:')){$finance->updateFranchiseSandboxTest($payment);}else{$finance->upsertPayment($payment);$confirmedEnrollment=$studentEnrollments->handlePaymentUpdate((string)($payment['id']??''),(string)($payment['status']??''));if($confirmedEnrollment!==null){try{$release=$avaEnrollmentReleaser->release($confirmedEnrollment);if(($release['status']??'')==='released')$avaAccessNotifier->notify($confirmedEnrollment);}catch(Throwable){}}}}if($subscription!==null)$finance->upsertSubscription($subscription);if($checkout!==null)$financeCatalog->updateFromWebhook($checkout);$finance->finishWebhook($eventId);}catch(Throwable$e){$finance->finishWebhook($eventId,mb_substr($e->getMessage(),0,500));return Response::text("Falha temporária.\n",500);}
