            $returnBase = rtrim($config->string('app.url'), '/') . '/checkout/return/';
            $customerData = array_filter([
                'name' => (string) $customer['name'],
                'cpfCnpj' => (string) ($customer['cpf_cnpj'] ?? ''),
                'email' => (string) ($customer['email'] ?? ''),
                'phone' => (string) ($customer['mobile_phone'] ?: $customer['phone'] ?: ''),
                'address' => (string) $customer['address'],
                'addressNumber' => (string) $customer['address_number'],
                'complement' => (string) ($customer['complement'] ?? ''),
                'province' => (string) $customer['province'],
                'postalCode' => (string) $customer['postal_code'],
            ], static fn(string $value): bool => $value !== '');
            $payload = [
                'billingTypes' => $billing,
